/* Short, local activities for the reviewed chapters; no scores or account needed. */
const summaryAttempts=new Map();
function summaryActivityContext(){const chapter=rangkumanCache.get(rangkumanState.chapter);if(!chapter?.interactive)return null;const index=summaryInteger(rangkumanState.studyPattern,0,chapter.patterns.length-1);rangkumanState.studyPattern=index;const pattern=chapter.patterns[index];if(!summaryAttempts.has(pattern.id))summaryAttempts.set(pattern.id,{token:null,order:[],checked:false,revealed:false});return {chapter,pattern,index,attempt:summaryAttempts.get(pattern.id)}}
function summaryActivityRefresh(focusId){const context=summaryActivityContext(),host=document.getElementById('summary-activity-host');if(!context||!host)return;host.innerHTML=summaryActivityBody(context.chapter);if(focusId)document.getElementById(focusId)?.focus({preventScroll:true})}
function summaryChoosePattern(index){const c=rangkumanCache.get(rangkumanState.chapter);if(!c?.interactive)return;rangkumanState.studyPattern=summaryInteger(index,0,c.patterns.length-1);rangkumanState.studyStage=0;rememberRangkuman();summaryActivityRefresh('summary-activity-title')}
function summaryChooseStage(stage){if(!summaryActivityContext())return;rangkumanState.studyStage=summaryInteger(stage,0,2);rememberRangkuman();summaryActivityRefresh('summary-activity-title')}
function summaryExploreToken(index){const c=summaryActivityContext();if(!c||!Number.isInteger(index)||!c.pattern.example.tokens[index])return;c.attempt.token=index;summaryActivityRefresh('summary-token-'+index)}
function summaryActivitySpeak(index){const c=summaryActivityContext(),t=c?.pattern.example.tokens[index];if(t&&typeof speak==='function')speak(t.kana)}
function summaryChoosePiece(index){const c=summaryActivityContext();if(!c||!Number.isInteger(index)||!c.pattern.example.tokens[index]||c.attempt.order.includes(index))return;c.attempt.order.push(index);c.attempt.checked=false;const next=c.pattern.example.tokens.findIndex((_,i)=>!c.attempt.order.includes(i));summaryActivityRefresh(next<0?'summary-build-check':'summary-piece-'+next)}
function summaryRemovePiece(position){const c=summaryActivityContext();if(!c||!Number.isInteger(position)||position<0||position>=c.attempt.order.length)return;const [index]=c.attempt.order.splice(position,1);c.attempt.checked=false;summaryActivityRefresh('summary-piece-'+index)}
function summaryResetActivity(){const c=summaryActivityContext();if(!c)return;c.attempt.order=[];c.attempt.checked=false;c.attempt.revealed=false;summaryActivityRefresh('summary-piece-0')}
function summaryCheckOrder(){const c=summaryActivityContext();if(!c||c.attempt.order.length!==c.pattern.example.tokens.length)return;c.attempt.checked=true;summaryActivityRefresh('summary-activity-feedback')}
function summaryRevealActivity(){const c=summaryActivityContext();if(!c)return;c.attempt.revealed=true;summaryActivityRefresh('summary-activity-feedback')}
function summaryOrderMatches(pattern,attempt){return attempt.order.map(i=>pattern.example.tokens[i].kana).join('\u0000')===pattern.example.tokens.map(t=>t.kana).join('\u0000')}
function summaryActivityHTML(c){return '<section class="summary-activity"><div class="summary-activity-intro"><span class="summary-step">COBA · PAHAMI · ULANGI</span><button class="summary-help-link" onclick="summaryOpenHelp()">? Bantuan belajar</button></div><div class="summary-note-tools"><button onclick="summaryToggleKanji()" aria-pressed="'+summaryKanji+'">'+(summaryKanji?'Kanji aktif':'Tampilkan kanji')+'</button></div><div id="summary-activity-host">'+summaryActivityBody(c)+'</div></section><button class="summary-switch-section" onclick="summaryChapterSection(\'kotoba\')">Bekal '+(c.vocab?.length??c.vocabCount??0)+' kata Bab '+c.id+' →</button>'}
function summaryActivityBody(c){const context=summaryActivityContext();if(!context)return '';const {pattern:p,index,attempt:a}=context,stage=summaryInteger(rangkumanState.studyStage,0,2);rangkumanState.studyStage=stage;const ex=p.example;
 const picker='<nav class="summary-pattern-picker" aria-label="Pilih pola dalam bab">'+c.patterns.map((item,i)=>'<button aria-label="Pola '+(i+1)+': '+esc(item.meaning)+'" aria-pressed="'+(i===index)+'" onclick="summaryChoosePattern('+i+')">'+(i+1)+'<span>'+esc(item.meaning)+'</span></button>').join('')+'</nav>';
 const steps='<div class="summary-activity-stages" role="group" aria-label="Langkah belajar">'+['Pahami','Bongkar','Coba'].map((label,i)=>'<button '+(stage===i?'aria-current="step"':'')+' aria-pressed="'+(stage===i)+'" onclick="summaryChooseStage('+i+')"><span>'+(i+1)+'</span>'+label+'</button>').join('')+'</div>';
 let body='';
 if(stage===0)body='<div class="summary-situation"><small>YANG INGIN KAMU KATAKAN</small><p>'+esc(ex.meaning)+'</p></div><p class="summary-activity-gist">'+esc(p.learning.gist)+'</p><div class="summary-recipe"><strong>Rangkai seperti ini</strong><p>'+esc(p.learning.recipe)+'</p></div><details class="summary-activity-reference"><summary>Baru belajar? Arti tanda dalam pola</summary><p>N = kata benda: orang, tempat, atau hal. V = kata kerja: tindakan. A／S1／S2 hanya penanda bagian. + berarti sambungkan; → berarti hasil perubahan. Negatif berarti tidak／bukan; lampau berarti yang sudah lewat.</p><p>Bentuk kamus ialah bentuk yang dicari di kamus. Buang ます berarti buang akhirnya saja: たべます → たべ. Golongan I／II／III menunjukkan kelompok perubahan kata kerja.</p></details><button class="summary-activity-primary" onclick="summaryChooseStage(1)">Bongkar contohnya →</button>';
 if(stage===1){const selected=a.token===null?null:ex.tokens[a.token];body='<p class="summary-activity-hint">Ketuk satu potongan untuk melihat tugasnya dalam kalimat.</p><div class="summary-explore-tokens">'+ex.tokens.map((t,i)=>'<button id="summary-token-'+i+'" class="'+(t.particle?'is-marker':'')+'" aria-pressed="'+(a.token===i)+'" onclick="summaryExploreToken('+i+')"><span lang="ja">'+esc(summaryKanji?t.jp:t.kana)+'</span><small>Ketuk</small></button>').join('')+'</div><div class="summary-token-insight" aria-live="polite">'+(selected?'<span lang="ja">'+esc(selected.kana)+'</span><p>'+esc(selected.meaning)+'</p><button aria-label="Dengarkan potongan '+esc(selected.kana)+'" onclick="summaryActivitySpeak('+a.token+')">♪ Dengarkan</button>':'<p>Mulai dari kata yang membuatmu penasaran. Kotak jingga menyoroti penanda.</p>')+'</div><p class="summary-japanese" lang="ja">'+esc(summaryKanji?ex.jp:ex.kana)+'</p><p class="summary-romaji">'+esc(bunpoExampleRomaji(ex.kana))+'</p><p class="summary-example-meaning">'+esc(ex.meaning)+'</p><details class="summary-activity-reference"><summary>Catatan penggunaan</summary><p>'+esc(p.learning.note)+'</p></details>'+summaryIllustration(c.id,index)+'<button class="summary-activity-primary" onclick="summaryChooseStage(2)">Sekarang coba sendiri →</button>'}
 if(stage===2){
  body='<div class="summary-situation"><small>SEKARANG GILIRANMU</small><p>'+esc(ex.meaning)+'</p></div>';
  if(p.learning.practice==='recall')body+='<p class="summary-activity-hint">Coba ucapkan ungkapannya, lalu buka contoh untuk mencocokkan. Suaramu tidak direkam atau dinilai.</p><button class="summary-activity-primary" onclick="summaryRevealActivity()">Buka contoh ungkapannya</button>'+(a.revealed?'<div id="summary-activity-feedback" class="summary-activity-feedback" tabindex="-1" role="status"><p lang="ja">'+esc(ex.kana)+'</p><p class="summary-romaji">'+esc(bunpoExampleRomaji(ex.kana))+'</p><p class="summary-example-meaning">'+esc(ex.meaning)+'</p><p>'+esc(p.learning.note)+'</p></div>':'');
  else {
   const order=ex.tokens.map((_,i)=>i).reverse();
   body+='<p class="summary-activity-hint">Ketuk potongan mengikuti urutan contoh. Ketuk potongan di jawaban untuk mengembalikannya.</p><div class="summary-build-answer" aria-label="Susunan jawaban">'+(a.order.length?a.order.map((i,pos)=>'<button aria-label="Kembalikan '+esc(ex.tokens[i].kana)+'" onclick="summaryRemovePiece('+pos+')">'+esc(summaryKanji?ex.tokens[i].jp:ex.tokens[i].kana)+'</button>').join(''):'<span>Kalimatmu akan muncul di sini.</span>')+'</div><div class="summary-piece-bank" aria-label="Pilihan potongan">'+order.map(i=>'<button id="summary-piece-'+i+'" '+(a.order.includes(i)?'disabled':'')+' onclick="summaryChoosePiece('+i+')">'+esc(summaryKanji?ex.tokens[i].jp:ex.tokens[i].kana)+'</button>').join('')+'</div><div class="summary-build-actions"><button id="summary-build-check" class="summary-activity-primary" '+(a.order.length===ex.tokens.length?'':'disabled')+' onclick="summaryCheckOrder()">Cocokkan susunan</button><button class="summary-quiet" onclick="summaryResetActivity()">Ulangi</button></div>';
   if(a.checked){const correct=summaryOrderMatches(p,a);body+='<div id="summary-activity-feedback" class="summary-activity-feedback '+(correct?'is-right':'is-retry')+'" tabindex="-1" role="status"><strong>'+(correct?'Pas, susunannya sama dengan contoh!':'Belum sama dengan urutan contoh. Coba perhatikan penandanya.')+'</strong><p>'+esc(p.learning.recipe)+'</p>'+(correct?'<p>'+esc(p.learning.note)+'</p>':'<details><summary>Lihat contoh sebagai petunjuk</summary><p lang="ja">'+esc(ex.kana)+'</p></details>')+'</div>'}
   body+='<p class="summary-order-note">Latihan ini mengikuti satu urutan contoh. Susunan lain bisa benar dalam konteks berbeda.</p>';
  }
  body+='<details class="summary-activity-reference"><summary>Ingat kembali penjelasannya</summary><p>'+esc(p.learning.gist)+'</p>'+summaryBlocksHTML(p.blocks.filter(b=>b.type==='table'||b.type==='list'))+'<p>'+esc(p.learning.note)+'</p></details>'+(index<c.patterns.length-1?'<button class="summary-activity-primary" onclick="summaryChoosePattern('+(index+1)+')">Coba pola '+(index+2)+' →</button>':'<p class="summary-activity-hint">Kamu boleh mengulang pola mana pun atau mencoba situasi lain di bawah.</p>');
 }
 return picker+'<div class="summary-activity-card"><div class="summary-activity-heading"><span>POLA '+(index+1)+' DARI '+c.patterns.length+'</span><h2 id="summary-activity-title" tabindex="-1">'+esc(p.title)+'</h2><p>'+esc(p.meaning)+'</p></div>'+steps+'<div class="summary-activity-content">'+body+'</div></div>'
}
